import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
const token=String.fromEnvironment('TMDB_TOKEN');
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData.dark(useMaterial3:true),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{List items=[];final saved=<int>{};final search=TextEditingController();String error='';bool busy=true;
@override void initState(){super.initState();load();}
Future<void> load([String q=''])async{if(token.isEmpty){setState(()=>{error='Configure TMDB_TOKEN with --dart-define.',busy=false});return;}setState(()=>busy=true);try{final path=q.isEmpty?'/movie/popular':'/search/movie';final uri=Uri.https('api.themoviedb.org','3$path',{'query':q,'language':'en-US','page':'1'});final r=await http.get(uri,headers:{'Authorization':'Bearer $token','accept':'application/json'});if(r.statusCode!=200)throw Exception('TMDB error: '+r.statusCode.toString());setState(()=>items=jsonDecode(r.body)['results']??[]);}catch(e){setState(()=>error=e.toString());}finally{setState(()=>busy=false);}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Malkify Movies')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(controller:search,onSubmitted:load,decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search movies',border:OutlineInputBorder()))),if(error.isNotEmpty)Text(error),if(busy)const CircularProgressIndicator()else Expanded(child:GridView.builder(padding:const EdgeInsets.all(10),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:.58,crossAxisSpacing:10,mainAxisSpacing:10),itemCount:items.length,itemBuilder:(c,i){final m=items[i];final id=m['id'] as int;final p=m['poster_path'];return Card(clipBehavior:Clip.antiAlias,child:Column(children:[Expanded(child:p==null?const Icon(Icons.movie):Image.network('https://image.tmdb.org/t/p/w500$p',fit:BoxFit.cover,width:double.infinity)),Text(m['title']??'Untitled',maxLines:2,overflow:TextOverflow.ellipsis),IconButton(onPressed:()=>setState(()=>saved.contains(id)?saved.remove(id):saved.add(id)),icon:Icon(saved.contains(id)?Icons.bookmark:Icons.bookmark_border))]));}))]));}}
